package com.steven.assets.service.srpp.report;

import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.*;
import com.steven.assets.repository.*;
import com.steven.assets.service.*;
import com.steven.assets.service.srpp.decision.DecisionPolicyAuthority;
import org.junit.jupiter.api.Test;
import java.time.*;
import java.util.*;
import static org.assertj.core.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.mockito.ArgumentMatchers.*;

class SrppReportExtraCaptureAdapterTest {
    @Test void alreadyFrozenBondSourcesAreReusedWithoutASecondMarketReadAndCalendarIsShared()throws Exception{
        ObjectMapper mapper=new ObjectMapper().findAndRegisterModules().enable(DeserializationFeature.USE_BIG_DECIMAL_FOR_FLOATS);
        PriceQueryService prices=mock(PriceQueryService.class);MarketDataService market=mock(MarketDataService.class);TradingRadarService radar=mock(TradingRadarService.class);StockPriceHistoryRepository history=mock(StockPriceHistoryRepository.class);StockDividendHistoryRepository dividends=mock(StockDividendHistoryRepository.class);TechnicalIndicatorService indicators=mock(TechnicalIndicatorService.class);
        when(market.isTradingDayCachedOnly(anyString(),any())).thenReturn(Optional.of(false));
        ObjectNode frozen=mapper.createObjectNode();Set<String> bonds=Set.of("00865B","00719B","00697B");for(String code:bonds){ObjectNode q=frozen.putObject("quote:"+code);q.putObject("rawQuote").put("stockCode",code).put("market","台股").put("price","10");q.putObject("rawNav").put("premiumDiscountPct","0");frozen.putArray("daily:"+code);frozen.putArray("dividends:"+code);frozen.putObject("book:"+code).put("source","FUBON_BOOKS");frozen.putObject("radar:"+code).put("ownerUserId",7);}
        JsonNode model=mapper.readTree(new DecisionPolicyAuthority().modelBytes());Instant at=Instant.now();var capture=new SrppReportExtraCaptureAdapter(prices,market,radar,history,dividends,indicators,mapper).capture(7,LocalDate.parse("2026-10-08"),"12:00",at,model,mapper.createObjectNode(),frozen);
        for(String code:bonds){JsonNode body=capture.sources().path("market:台股:"+code);assertThat(body.path("quote")).isEqualTo(frozen.path("quote:"+code).path("rawQuote"));verify(history,never()).findByStockCodeAndMarketAndTradingDateBetweenOrderByTradingDateAsc(eq(code),anyString(),any(),any());verify(dividends,never()).findByStockSinceYear(eq(code),anyString(),anyInt());verify(radar,never()).getStockDetailForOwner(anyLong(),eq(code),anyString());verify(indicators,never()).indicatorSeries(eq(code),anyString(),any(),any());verify(market,never()).getQuoteDetail(eq(code),anyString());}
        verify(market,times(550)).isTradingDayCachedOnly(eq("台股"),any());verify(market,times(550)).isTradingDayCachedOnly(eq("美股"),any());assertThat(capture.sourceVector().path("dca-identity").path("validation").asText()).isEqualTo("UNAVAILABLE");Set<String> sourceIds=new TreeSet<>(),vectorIds=new TreeSet<>();capture.sources().fieldNames().forEachRemaining(sourceIds::add);capture.sourceVector().fieldNames().forEachRemaining(vectorIds::add);assertThat(vectorIds).isEqualTo(sourceIds);
    }    @Test void validCompositeCanBeVerifiedAndMissingIdentityOrCalendarStaysUnknown()throws Exception{
        ObjectMapper mapper=new ObjectMapper();ObjectNode body=mapper.createObjectNode();body.put("symbol","00713").put("market","台股").put("calendarVerified",true);body.putArray("completedSessions").add("2026-10-07");body.putArray("daily").addObject().put("tradingDate","2026-10-07").put("trusted",true).put("closePrice","50");body.putArray("dividends");body.putArray("indicators").addObject().put("tradingDate","2026-10-07");body.putObject("nav").put("nav","50");ObjectNode book=body.putObject("book");book.put("available",true);for(int i=0;i<5;i++)book.withArray("levels").addObject().put("askPrice","50");body.putObject("quote").put("stockCode","00713").put("market","台股").put("source","FUBON_LIVE_CACHE").put("quoteStatus","LIVE").put("closed",false).put("price","50").put("updatedAt","2026-10-08T04:00:00Z").put("tradingDate","2026-10-08");ObjectNode radar=body.putObject("radar");radar.put("ruleVersion","CURRENT").put("actionPolicyVersion","EVIDENCE_GATE_V1").put("generatedAt","2026-10-08T04:00:00Z");radar.putObject("stock").put("stockCode","00713").put("market","台股").put("asOfDate","2026-10-08").put("dataComplete",true);Instant at=Instant.parse("2026-10-08T04:01:00Z");assertThat(SrppReportExtraCaptureAdapter.assess(body,LocalDate.parse("2026-10-08"),at)).isEqualTo(new SrppReportExtraCaptureAdapter.SourceQuality("COMPLETE","VERIFIED"));((ObjectNode)body.path("quote")).put("market","美股");assertThat(SrppReportExtraCaptureAdapter.assess(body,LocalDate.parse("2026-10-08"),at).validation()).isEqualTo("UNAVAILABLE");body.put("calendarVerified",false);assertThat(SrppReportExtraCaptureAdapter.assess(body,LocalDate.parse("2026-10-08"),at).coverage()).isEqualTo("NONE");
    }
    @Test void verifiedCurrentYearCalendarPrefixDoesNotLoseUsableRecentSessionsAtOlderUnknownYear()throws Exception{ObjectMapper mapper=new ObjectMapper().findAndRegisterModules();PriceQueryService prices=mock(PriceQueryService.class);MarketDataService market=mock(MarketDataService.class);TradingRadarService radar=mock(TradingRadarService.class);StockPriceHistoryRepository history=mock(StockPriceHistoryRepository.class);StockDividendHistoryRepository dividends=mock(StockDividendHistoryRepository.class);TechnicalIndicatorService indicators=mock(TechnicalIndicatorService.class);when(market.isTradingDayCachedOnly(anyString(),any())).thenAnswer(call->{LocalDate day=call.getArgument(1);return day.getYear()==2026?Optional.of(day.getDayOfWeek().getValue()<=5):Optional.empty();});var capture=new SrppReportExtraCaptureAdapter(prices,market,radar,history,dividends,indicators,mapper).capture(7,LocalDate.parse("2026-10-08"),"12:00",Instant.now(),mapper.readTree(new DecisionPolicyAuthority().modelBytes()),mapper.createObjectNode(),mapper.createObjectNode());JsonNode body=capture.sources().path("market:台股:00865B");assertThat(body.path("calendarVerified").asBoolean()).isTrue();assertThat(body.path("lookbackComplete").asBoolean()).isFalse();assertThat(body.path("calendarCoverageStart").asText()).isEqualTo("2026-01-01");assertThat(body.path("calendarUnknownDate").asText()).isEqualTo("2025-12-31");assertThat(body.path("completedSessions").size()).isGreaterThan(20);assertThat(body.path("completedSessions").get(0).asText()).startsWith("2026-");}

}
